# Inhalt des Java-Handbuchs. Bei Einträgen mit "code" und "out" prüft test_book.py die Ausgabe.
# Bewusst neutrale Beispiele (Obst, Zahlen, Namen), damit keine Levellösung verraten wird.
# Zeilen, die mit class/interface/enum beginnen, stehen im echten Programm außerhalb von main,
# Zeilen mit static sind Methoden in Main. Alles andere läuft in main.
BOOK = [
    {"title": "Grundregeln", "items": [
        {"name": "Aufbau eines Programms", "desc": "Java-Code steht immer in einer Klasse. Das Programm startet in `main` und läuft dort von oben nach unten.",
         "code": "System.out.println(\"zuerst\");\nSystem.out.println(\"danach\");", "out": "zuerst\ndanach\n"},
        {"name": "Semikolon ;", "desc": "Jede Anweisung endet mit einem Semikolon. Zeilenumbrüche und Einrückung sind dem Compiler egal, sie helfen nur dir."},
        {"name": "Blöcke { }", "desc": "Geschweifte Klammern fassen Anweisungen zu einem Block zusammen: der Körper von Klassen, Methoden, Schleifen und if."},
        {"name": "Groß- und Kleinschreibung", "desc": "`name` und `Name` sind verschieden. Klassen beginnen groß (`String`), Variablen und Methoden klein (`anzahl`, `geheZu`)."},
        {"name": "Kommentare", "desc": "`//` bis zum Zeilenende, `/* ... */` über mehrere Zeilen. Der Compiler ignoriert beides.",
         "code": "// Das hier wird nicht ausgeführt\nSystem.out.println(\"Hallo\");  // auch das nicht", "out": "Hallo\n"},
        {"name": "System.out.println", "desc": "Schreibt eine Zeile ins Terminal. Mit `+` hängst du Text und Werte aneinander.",
         "code": "int alter = 20;\nSystem.out.println(\"Alter: \" + alter);", "out": "Alter: 20\n"},
        {"name": "import", "desc": "Klassen aus anderen Paketen musst du oben importieren. `import java.util.*;` holt Listen, Maps und Co."},
        {"name": "Compiler", "desc": "Java wird erst übersetzt, dann ausgeführt. Tippfehler und falsche Typen findet der Compiler schon vorher: Dann läuft gar nichts, und im Terminal steht die Zeile."},
    ]},
    {"title": "Variablen und Datentypen", "items": [
        {"name": "Variable deklarieren", "desc": "Erst der Typ, dann der Name. Der Typ steht nur beim ersten Mal.",
         "code": "int alter = 25;\nalter = alter + 1;\nSystem.out.println(alter);", "out": "26\n"},
        {"name": "int, double", "desc": "`int` ist eine ganze Zahl, `double` eine Kommazahl (mit Punkt). Teilen zwei `int`, fällt der Rest weg.",
         "code": "System.out.println(7 / 2);\nSystem.out.println(7 / 2.0);", "out": "3\n3.5\n"},
        {"name": "boolean", "desc": "Wahrheitswert: `true` oder `false`. Das kommt bei Vergleichen heraus.",
         "code": "boolean gross = 5 > 3;\nSystem.out.println(gross);", "out": "true\n"},
        {"name": "char", "desc": "Ein einzelnes Zeichen in einfachen Anführungszeichen.",
         "code": "char c = 'A';\nSystem.out.println(c);", "out": "A\n"},
        {"name": "String", "desc": "Text in doppelten Anführungszeichen. `String` ist eine Klasse, darum groß geschrieben.",
         "code": "String name = \"Mia\";\nSystem.out.println(name.length());\nSystem.out.println(name.toUpperCase());", "out": "3\nMIA\n"},
        {"name": "Primitive und Referenzen", "desc": "`int`, `double`, `boolean`, `char` speichern den Wert selbst. Alles andere (String, Arrays, Objekte) sind Referenzen: Die Variable zeigt auf ein Objekt, oder auf `null`."},
        {"name": "final", "desc": "Eine `final`-Variable bekommt genau einmal einen Wert.",
         "code": "final int MAX = 10;\nSystem.out.println(MAX);", "out": "10\n"},
        {"name": "var", "desc": "Mit `var` leitet der Compiler den Typ selbst ab. Der Typ steht trotzdem fest.",
         "code": "var zahl = 42;\nvar text = \"Hallo\";\nSystem.out.println(zahl + \" \" + text);", "out": "42 Hallo\n"},
        {"name": "Typumwandlung", "desc": "Von `double` nach `int` nur mit Cast: Die Nachkommastellen fallen weg. Text wird mit `Integer.parseInt` zur Zahl.",
         "code": "int ganz = (int) 3.9;\nint zahl = Integer.parseInt(\"7\") + 1;\nSystem.out.println(ganz + \" \" + zahl);", "out": "3 8\n"},
    ]},
    {"title": "Rechnen, Vergleichen, Logik", "items": [
        {"name": "+  -  *  /  %", "desc": "Grundrechenarten. `%` liefert den Rest beim Teilen. Mit `% 2 == 0` prüfst du, ob eine Zahl gerade ist.",
         "code": "System.out.println(7 % 3);\nSystem.out.println(10 % 2 == 0);", "out": "1\ntrue\n"},
        {"name": "++  --  +=  -=", "desc": "Kurzformen: `i++` zählt um 1 hoch, `x += 5` addiert 5.",
         "code": "int punkte = 10;\npunkte += 5;\npunkte++;\nSystem.out.println(punkte);", "out": "16\n"},
        {"name": "==  !=  <  >  <=  >=", "desc": "Vergleiche. Zum Vergleichen **zwei** Gleichheitszeichen, ein einzelnes `=` weist zu.",
         "code": "System.out.println(3 == 3);\nSystem.out.println(3 != 3);\nSystem.out.println(2 <= 3);", "out": "true\nfalse\ntrue\n"},
        {"name": "&&  ||  !", "desc": "`&&`: beides muss stimmen. `||`: eines reicht. `!`: dreht das Ergebnis um. Ist das Ergebnis schon nach dem linken Teil klar, wird der rechte nicht mehr ausgewertet.",
         "code": "System.out.println(true && false);\nSystem.out.println(true || false);\nSystem.out.println(!true);", "out": "false\ntrue\nfalse\n"},
        {"name": "Math", "desc": "Fertige Rechenfunktionen.",
         "code": "System.out.println(Math.max(3, 8));\nSystem.out.println(Math.abs(-4));\nSystem.out.println(Math.pow(2, 3));", "out": "8\n4\n8.0\n"},
        {"name": "Bedingter Ausdruck ? :", "desc": "Kurzes if als Wert: Bedingung `?` Wert wenn wahr `:` Wert wenn falsch.",
         "code": "int alter = 15;\nString text = alter >= 18 ? \"erwachsen\" : \"minderjährig\";\nSystem.out.println(text);", "out": "minderjährig\n"},
    ]},
    {"title": "Bedingungen", "items": [
        {"name": "if / else", "desc": "Die Bedingung steht in runden Klammern. `else` läuft, wenn sie nicht stimmt.",
         "code": "int temp = 10;\nif (temp > 25) {\n    System.out.println(\"heiß\");\n} else {\n    System.out.println(\"kühl\");\n}", "out": "kühl\n"},
        {"name": "else if", "desc": "Prüft weitere Fälle. Nur der erste passende Block läuft.",
         "code": "int note = 2;\nif (note == 1) {\n    System.out.println(\"sehr gut\");\n} else if (note == 2) {\n    System.out.println(\"gut\");\n} else {\n    System.out.println(\"geht so\");\n}", "out": "gut\n"},
        {"name": "Strings vergleichen: equals", "desc": "Strings vergleicht man mit `.equals(...)`. `==` prüft bei Objekten nur, ob es **dasselbe** Objekt ist, nicht ob der Inhalt gleich ist.",
         "code": "String a = \"Hallo\";\nString b = new String(\"Hallo\");\nSystem.out.println(a == b);\nSystem.out.println(a.equals(b));", "out": "false\ntrue\n"},
        {"name": "switch", "desc": "Unterscheidet viele feste Werte. Mit `->` läuft nur der passende Zweig.",
         "code": "String tag = \"Sa\";\nswitch (tag) {\n    case \"Sa\", \"So\" -> System.out.println(\"Wochenende\");\n    default -> System.out.println(\"Arbeitstag\");\n}", "out": "Wochenende\n"},
    ]},
    {"title": "Schleifen", "items": [
        {"name": "for", "desc": "Drei Teile: Startwert; Bedingung; Schritt. Läuft, solange die Bedingung stimmt.",
         "code": "for (int i = 0; i < 3; i++) {\n    System.out.println(i);\n}", "out": "0\n1\n2\n"},
        {"name": "while", "desc": "Läuft, solange die Bedingung stimmt. Im Block muss sich etwas ändern, sonst endet sie nie.",
         "code": "int n = 3;\nwhile (n > 0) {\n    System.out.println(n);\n    n--;\n}", "out": "3\n2\n1\n"},
        {"name": "do while", "desc": "Wie while, aber der Block läuft mindestens einmal, weil erst am Ende geprüft wird.",
         "code": "int n = 0;\ndo {\n    System.out.println(\"einmal\");\n} while (n > 0);", "out": "einmal\n"},
        {"name": "for each", "desc": "Geht alle Elemente eines Arrays oder einer Sammlung durch, ohne Index.",
         "code": "String[] obst = { \"Apfel\", \"Birne\" };\nfor (String o : obst) {\n    System.out.println(o);\n}", "out": "Apfel\nBirne\n"},
        {"name": "break, continue", "desc": "`break` beendet die Schleife sofort, `continue` springt zur nächsten Runde.",
         "code": "for (int i = 0; i < 5; i++) {\n    if (i == 1) continue;\n    if (i == 3) break;\n    System.out.println(i);\n}", "out": "0\n2\n"},
    ]},
    {"title": "Methoden", "items": [
        {"name": "Methode definieren", "desc": "Rückgabetyp, Name, Parameter mit Typ. `void` gibt nichts zurück. Neben `main` müssen Methoden `static` sein.",
         "code": "static void gruesse(String name) {\n    System.out.println(\"Hallo \" + name);\n}\ngruesse(\"Mia\");", "out": "Hallo Mia\n"},
        {"name": "return", "desc": "Gibt einen Wert an die Stelle zurück, wo die Methode aufgerufen wurde, und beendet sie.",
         "code": "static int doppelt(int zahl) {\n    return zahl * 2;\n}\nSystem.out.println(doppelt(4) + 1);", "out": "9\n"},
        {"name": "Überladen", "desc": "Mehrere Methoden dürfen gleich heißen, wenn sich ihre Parameter unterscheiden.",
         "code": "static int summe(int a, int b) {\n    return a + b;\n}\nstatic int summe(int a, int b, int c) {\n    return a + b + c;\n}\nSystem.out.println(summe(1, 2) + \" \" + summe(1, 2, 3));", "out": "3 6\n"},
        {"name": "Wert oder Referenz", "desc": "Primitive Werte werden kopiert: Die Methode ändert nur ihre Kopie. Bei Objekten und Arrays wird die Referenz kopiert: Änderungen am Objekt sieht auch der Aufrufer.",
         "code": "static void aendere(int zahl, int[] feld) {\n    zahl = 99;\n    feld[0] = 99;\n}\nint z = 1;\nint[] f = { 1 };\naendere(z, f);\nSystem.out.println(z + \" \" + f[0]);", "out": "1 99\n"},
    ]},
    {"title": "Arrays und Strings", "items": [
        {"name": "Array anlegen", "desc": "Feste Länge, alle Elemente vom selben Typ. Der Index beginnt bei 0.",
         "code": "int[] a = { 5, 8, 2 };\nint[] leer = new int[3];\nSystem.out.println(a[0] + \" \" + a.length + \" \" + leer[2]);", "out": "5 3 0\n"},
        {"name": "Array durchlaufen", "desc": "Mit Index, wenn du die Position brauchst oder Werte ändern willst.",
         "code": "int[] a = { 5, 8, 2 };\nint summe = 0;\nfor (int i = 0; i < a.length; i++) {\n    summe += a[i];\n}\nSystem.out.println(summe);", "out": "15\n"},
        {"name": "2D-Array", "desc": "Ein Array von Arrays, z.B. für eine Karte: erst die Zeile, dann die Spalte.",
         "code": "boolean[][] karte = new boolean[2][3];\nkarte[1][2] = true;\nSystem.out.println(karte[1][2] + \" \" + karte[0][0]);", "out": "true false\n"},
        {"name": "String-Methoden", "desc": "Strings sind unveränderlich: Jede Methode liefert einen neuen String.",
         "code": "String s = \"Lagerhalle\";\nSystem.out.println(s.charAt(0));\nSystem.out.println(s.substring(0, 5));\nSystem.out.println(s.contains(\"halle\"));\nSystem.out.println(s.indexOf(\"h\"));", "out": "L\nLager\ntrue\n5\n"},
        {"name": "Arrays.toString", "desc": "Zeigt den Inhalt eines Arrays als Text (braucht `import java.util.*;`).",
         "code": "int[] a = { 3, 1, 2 };\nSystem.out.println(Arrays.toString(a));", "out": "[3, 1, 2]\n"},
    ]},
    {"title": "Klassen und Objekte", "items": [
        {"name": "Klasse, Feld, Konstruktor", "desc": "Die Klasse ist der Bauplan, `new` erzeugt ein Objekt. Der Konstruktor heißt wie die Klasse und füllt die Felder. `this` ist das Objekt selbst.",
         "code": "class Konto {\n    private int stand;\n\n    Konto(int start) {\n        this.stand = start;\n    }\n\n    void zahleEin(int betrag) {\n        stand += betrag;\n    }\n\n    int getStand() {\n        return stand;\n    }\n}\nKonto k = new Konto(100);\nk.zahleEin(50);\nSystem.out.println(k.getStand());", "out": "150\n"},
        {"name": "Sichtbarkeit", "desc": "`private`: nur in der Klasse selbst. Ohne Angabe: im selben Paket. `protected`: zusätzlich in Unterklassen. `public`: überall. Felder sind meist `private` und werden über Methoden gelesen (Kapselung)."},
        {"name": "static", "desc": "Gehört zur Klasse, nicht zu einem einzelnen Objekt. Alle Objekte teilen sich ein `static`-Feld.",
         "code": "class Zaehler {\n    static int anzahl = 0;\n\n    Zaehler() {\n        anzahl++;\n    }\n}\nnew Zaehler();\nnew Zaehler();\nSystem.out.println(Zaehler.anzahl);", "out": "2\n"},
        {"name": "null", "desc": "Eine Referenz, die auf kein Objekt zeigt. Rufst du darauf eine Methode auf, gibt es eine `NullPointerException`.",
         "code": "String s = null;\nSystem.out.println(s == null);", "out": "true\n"},
        {"name": "toString", "desc": "Bestimmt, wie ein Objekt als Text aussieht, z.B. bei println.",
         "code": "class Punkt {\n    int x, y;\n\n    Punkt(int x, int y) {\n        this.x = x;\n        this.y = y;\n    }\n\n    @Override\n    public String toString() {\n        return \"(\" + x + \", \" + y + \")\";\n    }\n}\nSystem.out.println(new Punkt(2, 3));", "out": "(2, 3)\n"},
        {"name": "enum", "desc": "Ein Typ mit festen, benannten Werten.",
         "code": "enum Ampel { ROT, GELB, GRUEN }\nAmpel a = Ampel.GELB;\nSystem.out.println(a + \" \" + (a == Ampel.GELB));", "out": "GELB true\n"},
    ]},
    {"title": "Vererbung", "items": [
        {"name": "extends, super, @Override", "desc": "Die Unterklasse erbt Felder und Methoden. `super(...)` ruft den Konstruktor der Oberklasse, `@Override` markiert eine überschriebene Methode.",
         "code": "class Tier {\n    protected String name;\n\n    Tier(String name) {\n        this.name = name;\n    }\n\n    void sprich() {\n        System.out.println(name + \" macht ein Geräusch\");\n    }\n}\nclass Katze extends Tier {\n    Katze(String name) {\n        super(name);\n    }\n\n    @Override\n    void sprich() {\n        System.out.println(name + \": Miau\");\n    }\n}\nTier t = new Katze(\"Mia\");\nt.sprich();", "out": "Mia: Miau\n"},
        {"name": "Statischer und dynamischer Typ", "desc": "`Tier t = new Katze(...)`: Der statische Typ (Tier) bestimmt, welche Methoden du aufrufen darfst. Der dynamische Typ (Katze) bestimmt, welche Version läuft (dynamische Bindung)."},
        {"name": "instanceof und Cast", "desc": "Prüft den dynamischen Typ. Danach kannst du auf den spezielleren Typ zugreifen.",
         "code": "Object o = \"Hallo\";\nif (o instanceof String s) {\n    System.out.println(s.length());\n}", "out": "5\n"},
        {"name": "abstract", "desc": "Von einer abstrakten Klasse gibt es keine Objekte. Abstrakte Methoden haben keinen Körper und müssen in der Unterklasse implementiert werden.",
         "code": "abstract class Form {\n    abstract double flaeche();\n}\nclass Quadrat extends Form {\n    double seite = 2;\n\n    @Override\n    double flaeche() {\n        return seite * seite;\n    }\n}\nForm f = new Quadrat();\nSystem.out.println(f.flaeche());", "out": "4.0\n"},
        {"name": "Object", "desc": "Jede Klasse erbt von `Object` und hat damit `toString()`, `equals()` und `hashCode()`. Wer `equals` überschreibt, muss auch `hashCode` passend überschreiben, sonst finden HashMap und HashSet die Objekte nicht."},
        {"name": "Exceptions", "desc": "Eine Ausnahme unterbricht den normalen Ablauf. Mit `try` / `catch` fängst du sie ab.",
         "code": "try {\n    int[] a = new int[2];\n    a[5] = 1;\n} catch (ArrayIndexOutOfBoundsException e) {\n    System.out.println(\"Index gibt es nicht\");\n}", "out": "Index gibt es nicht\n"},
    ]},
    {"title": "Interfaces", "items": [
        {"name": "interface, implements", "desc": "Ein Interface nennt Methoden ohne Körper. Eine Klasse, die es implementiert, muss sie alle anbieten. Eine Klasse kann mehrere Interfaces implementieren, aber nur von einer Klasse erben.",
         "code": "interface Fahrbar {\n    void fahre();\n}\nclass Rad implements Fahrbar {\n    @Override\n    public void fahre() {\n        System.out.println(\"Das Rad rollt\");\n    }\n}\nFahrbar f = new Rad();\nf.fahre();", "out": "Das Rad rollt\n"},
        {"name": "Comparable", "desc": "`compareTo` legt die natürliche Ordnung fest: negativ = ich komme zuerst, 0 = gleich, positiv = ich komme danach.",
         "code": "class Buch implements Comparable<Buch> {\n    int seiten;\n\n    Buch(int seiten) {\n        this.seiten = seiten;\n    }\n\n    @Override\n    public int compareTo(Buch other) {\n        return this.seiten - other.seiten;\n    }\n}\nList<Buch> regal = new ArrayList<>(List.of(new Buch(300), new Buch(120)));\nCollections.sort(regal);\nSystem.out.println(regal.get(0).seiten);", "out": "120\n"},
        {"name": "Comparator", "desc": "Eine Ordnung von außen, wenn die Klasse selbst nicht Comparable ist oder du anders sortieren willst.",
         "code": "List<String> namen = new ArrayList<>(List.of(\"Alexander\", \"Jo\", \"Mia\"));\nnamen.sort(Comparator.comparingInt(n -> n.length()));\nSystem.out.println(namen);", "out": "[Jo, Mia, Alexander]\n"},
        {"name": "Anonyme Klasse", "desc": "Eine Klasse ohne Namen, direkt an der Stelle erzeugt, wo du sie brauchst. Für Interfaces mit einer Methode nimmt man heute meist ein Lambda.",
         "code": "Runnable r = new Runnable() {\n    @Override\n    public void run() {\n        System.out.println(\"läuft\");\n    }\n};\nr.run();", "out": "läuft\n"},
    ]},
    {"title": "Generics", "items": [
        {"name": "Generische Klasse", "desc": "`T` ist ein Platzhalter für einen Typ, der beim Benutzen festgelegt wird. Der Compiler prüft die Typen, Casts sind nicht nötig.",
         "code": "class Box<T> {\n    private T inhalt;\n\n    void lege(T neu) {\n        inhalt = neu;\n    }\n\n    T hole() {\n        return inhalt;\n    }\n}\nBox<String> b = new Box<>();\nb.lege(\"Brief\");\nSystem.out.println(b.hole().length());", "out": "5\n"},
        {"name": "Generische Methode", "desc": "Der Typparameter steht vor dem Rückgabetyp.",
         "code": "static <T> T erstes(List<T> liste) {\n    return liste.get(0);\n}\nSystem.out.println(erstes(List.of(\"a\", \"b\")));", "out": "a\n"},
        {"name": "Wrapper-Klassen", "desc": "In spitzen Klammern stehen nur Klassen: `Integer` statt `int`, `Double` statt `double`, `Boolean` statt `boolean`. Java wandelt automatisch um (Autoboxing).",
         "code": "List<Integer> zahlen = new ArrayList<>();\nzahlen.add(5);\nint erste = zahlen.get(0);\nSystem.out.println(erste);", "out": "5\n"},
        {"name": "Beschränkung: extends", "desc": "`<T extends Comparable<T>>` erlaubt nur Typen, die vergleichbar sind. Dann darfst du `compareTo` aufrufen.",
         "code": "static <T extends Comparable<T>> T groesstes(T a, T b) {\n    return a.compareTo(b) >= 0 ? a : b;\n}\nSystem.out.println(groesstes(3, 8));\nSystem.out.println(groesstes(\"Apfel\", \"Birne\"));", "out": "8\nBirne\n"},
    ]},
    {"title": "Collections", "items": [
        {"name": "ArrayList", "desc": "Eine Liste, die wachsen kann. Zugriff über den Index in O(1), Einfügen vorne oder in der Mitte in O(n).",
         "code": "List<String> korb = new ArrayList<>();\nkorb.add(\"Apfel\");\nkorb.add(\"Birne\");\nkorb.remove(\"Apfel\");\nSystem.out.println(korb + \" \" + korb.size() + \" \" + korb.get(0));", "out": "[Birne] 1 Birne\n"},
        {"name": "LinkedList", "desc": "Eine verkettete Liste. Einfügen und Entfernen an den Enden in O(1), aber Zugriff über den Index in O(n)."},
        {"name": "HashMap", "desc": "Ordnet Schlüsseln Werte zu. Suchen und Einfügen im Schnitt in O(1). Die Reihenfolge ist nicht festgelegt.",
         "code": "Map<String, Integer> alter = new HashMap<>();\nalter.put(\"Mia\", 20);\nalter.put(\"Tom\", 25);\nSystem.out.println(alter.get(\"Mia\"));\nSystem.out.println(alter.containsKey(\"Eva\"));\nSystem.out.println(alter.getOrDefault(\"Eva\", 0));", "out": "20\nfalse\n0\n"},
        {"name": "Map durchlaufen", "desc": "`keySet()` liefert die Schlüssel, `values()` die Werte, `entrySet()` beides zusammen.",
         "code": "Map<String, Integer> preis = new TreeMap<>();\npreis.put(\"Brot\", 3);\npreis.put(\"Apfel\", 1);\nfor (Map.Entry<String, Integer> e : preis.entrySet()) {\n    System.out.println(e.getKey() + \" kostet \" + e.getValue());\n}", "out": "Apfel kostet 1\nBrot kostet 3\n"},
        {"name": "HashSet", "desc": "Eine Menge: Jedes Element kommt höchstens einmal vor. `contains` läuft im Schnitt in O(1).",
         "code": "Set<Integer> gesehen = new HashSet<>();\ngesehen.add(4);\ngesehen.add(4);\nSystem.out.println(gesehen.size() + \" \" + gesehen.contains(4));", "out": "1 true\n"},
        {"name": "List.of, Map.of", "desc": "Fabrikmethoden für kleine, **unveränderliche** Sammlungen. Zum Ändern in eine ArrayList kopieren.",
         "code": "List<Integer> fest = List.of(3, 1, 2);\nList<Integer> kopie = new ArrayList<>(fest);\nkopie.add(4);\nSystem.out.println(fest + \" \" + kopie);", "out": "[3, 1, 2] [3, 1, 2, 4]\n"},
        {"name": "Collections", "desc": "Hilfsklasse mit fertigen Algorithmen für Sammlungen.",
         "code": "List<Integer> z = new ArrayList<>(List.of(3, 1, 2));\nCollections.sort(z);\nSystem.out.println(z + \" \" + Collections.max(z));\nCollections.reverse(z);\nSystem.out.println(z);", "out": "[1, 2, 3] 3\n[3, 2, 1]\n"},
        {"name": "Stack und Queue", "desc": "Stapel (LIFO): zuletzt hinein, zuerst heraus. Warteschlange (FIFO): zuerst hinein, zuerst heraus. `ArrayDeque` kann beides.",
         "code": "Deque<Integer> stapel = new ArrayDeque<>();\nstapel.push(1);\nstapel.push(2);\nSystem.out.println(stapel.pop());\nQueue<Integer> schlange = new ArrayDeque<>();\nschlange.add(1);\nschlange.add(2);\nSystem.out.println(schlange.poll());", "out": "2\n1\n"},
    ]},
    {"title": "Lambdas", "items": [
        {"name": "Lambda-Ausdruck", "desc": "Eine Methode ohne Namen: Parameter `->` Ergebnis. Mit mehreren Anweisungen in geschweiften Klammern.",
         "code": "List<String> namen = new ArrayList<>(List.of(\"Tom\", \"Alexander\", \"Jo\"));\nnamen.sort((a, b) -> a.length() - b.length());\nnamen.forEach(n -> System.out.println(n));", "out": "Jo\nTom\nAlexander\n"},
        {"name": "Funktionales Interface", "desc": "Ein Interface mit genau einer abstrakten Methode. Überall, wo so eines erwartet wird, passt ein Lambda.",
         "code": "interface Rechnung {\n    int rechne(int a, int b);\n}\nRechnung plus = (a, b) -> a + b;\nSystem.out.println(plus.rechne(2, 3));", "out": "5\n"},
        {"name": "Predicate, Function, Consumer, Supplier", "desc": "Fertige funktionale Interfaces aus `java.util.function`: prüft etwas, wandelt um, verbraucht einen Wert, liefert einen Wert.",
         "code": "Predicate<Integer> gerade = z -> z % 2 == 0;\nFunction<Integer, Integer> quadrat = z -> z * z;\nSystem.out.println(gerade.test(4) + \" \" + quadrat.apply(5));", "out": "true 25\n"},
        {"name": "Methodenreferenz ::", "desc": "Kurzform für ein Lambda, das nur eine vorhandene Methode aufruft.",
         "code": "List<String> namen = List.of(\"Mia\", \"Tom\");\nnamen.forEach(System.out::println);", "out": "Mia\nTom\n"},
        {"name": "removeIf", "desc": "Entfernt alle Elemente, für die das Lambda `true` liefert.",
         "code": "List<Integer> z = new ArrayList<>(List.of(1, 8, 3, 9));\nz.removeIf(x -> x > 5);\nSystem.out.println(z);", "out": "[1, 3]\n"},
    ]},
    {"title": "Streams", "items": [
        {"name": "Pipeline", "desc": "Quelle, Zwischenschritte, ein Abschluss. Erst der Abschluss startet die Arbeit, die Quelle bleibt unverändert.",
         "code": "List<Integer> z = List.of(5, 12, 8, 3);\nz.stream()\n    .filter(x -> x > 4)\n    .map(x -> x * 10)\n    .forEach(x -> System.out.println(x));", "out": "50\n120\n80\n"},
        {"name": "sorted, limit, distinct", "desc": "Sortieren, die ersten n nehmen, Duplikate entfernen.",
         "code": "List<Integer> z = List.of(5, 3, 5, 9, 1);\nSystem.out.println(z.stream().distinct().sorted().limit(3).toList());", "out": "[1, 3, 5]\n"},
        {"name": "collect, toList", "desc": "Sammelt das Ergebnis wieder in einer Liste.",
         "code": "List<String> namen = List.of(\"mia\", \"tom\");\nList<String> gross = namen.stream().map(n -> n.toUpperCase()).collect(Collectors.toList());\nSystem.out.println(gross);", "out": "[MIA, TOM]\n"},
        {"name": "count, sum, max", "desc": "Abschlüsse, die einen einzelnen Wert liefern. `mapToInt` macht daraus einen Zahlen-Stream.",
         "code": "List<Integer> z = List.of(4, 7, 1);\nSystem.out.println(z.stream().filter(x -> x > 2).count());\nSystem.out.println(z.stream().mapToInt(x -> x).sum());\nSystem.out.println(z.stream().max(Comparator.naturalOrder()).get());", "out": "2\n12\n7\n"},
        {"name": "anyMatch, allMatch", "desc": "Prüfen, ob mindestens ein oder alle Elemente eine Bedingung erfüllen.",
         "code": "List<Integer> z = List.of(4, 7, 1);\nSystem.out.println(z.stream().anyMatch(x -> x > 6));\nSystem.out.println(z.stream().allMatch(x -> x > 6));", "out": "true\nfalse\n"},
    ]},
    {"title": "Komplexität", "items": [
        {"name": "O-Notation", "desc": "Beschreibt, wie der Aufwand mit der Eingabegröße n wächst. Konstante Faktoren zählen nicht, nur die Größenordnung. Meist betrachtet man den schlechtesten Fall."},
        {"name": "O(1) konstant", "desc": "Unabhängig von n: Zugriff auf `a[i]`, Einfügen in eine HashMap, push und pop auf einem Stapel."},
        {"name": "O(log n) logarithmisch", "desc": "Jeder Schritt halbiert das Problem: binäre Suche, Suchen im ausgeglichenen Suchbaum. Bei einer Million Elementen etwa 20 Schritte."},
        {"name": "O(n) linear", "desc": "Jedes Element einmal ansehen: lineare Suche, Summe, Maximum, Durchlaufen einer Liste."},
        {"name": "O(n log n)", "desc": "Gute Sortierverfahren: Quicksort (im Schnitt), Mergesort, Heapsort. Besser geht vergleichsbasiertes Sortieren nicht."},
        {"name": "O(n²) quadratisch", "desc": "Zwei Schleifen ineinander: Bubblesort, Selectionsort, Insertionsort. Doppelt so viele Daten, viermal so viel Arbeit."},
        {"name": "O(2ⁿ) exponentiell", "desc": "Alle Möglichkeiten durchprobieren (Exhaustion), z.B. alle Teilmengen. Schon bei kleinen n unbrauchbar, deshalb schneidet Backtracking aussichtslose Wege früh ab."},
        {"name": "Schritte zählen", "desc": "Zwei Schleifen ineinander über n Elemente laufen n · n Mal.",
         "code": "int n = 4;\nint schritte = 0;\nfor (int i = 0; i < n; i++) {\n    for (int j = 0; j < n; j++) {\n        schritte++;\n    }\n}\nSystem.out.println(schritte);", "out": "16\n"},
    ]},
    {"title": "Rekursion", "items": [
        {"name": "Basisfall und Rekursionsschritt", "desc": "Eine rekursive Methode ruft sich selbst mit einem kleineren Problem auf. Der Basisfall beendet die Kette.",
         "code": "static int fakultaet(int n) {\n    if (n == 0) {\n        return 1;\n    }\n    return n * fakultaet(n - 1);\n}\nSystem.out.println(fakultaet(5));", "out": "120\n"},
        {"name": "Mehrfache Rekursion", "desc": "Zwei Selbstaufrufe pro Aufruf ergeben einen Baum von Aufrufen. Bei Fibonacci wächst er exponentiell, weil dieselben Werte immer wieder berechnet werden.",
         "code": "static int fib(int n) {\n    if (n < 2) {\n        return n;\n    }\n    return fib(n - 1) + fib(n - 2);\n}\nSystem.out.println(fib(10));", "out": "55\n"},
        {"name": "Türme von Hanoi", "desc": "Klassiker: n Scheiben von A nach C. Erst n-1 Scheiben auf den Hilfsstab, dann die größte ans Ziel, dann die n-1 hinterher. Das sind 2ⁿ - 1 Züge.",
         "code": "static int zuege(int n) {\n    if (n == 0) {\n        return 0;\n    }\n    return zuege(n - 1) + 1 + zuege(n - 1);\n}\nSystem.out.println(zuege(3));", "out": "7\n"},
        {"name": "Backtracking", "desc": "Systematisches Ausprobieren: einen Schritt wählen, rekursiv weitersuchen, bei einer Sackgasse den Schritt zurücknehmen und den nächsten probieren. Typisch für Labyrinthe, das Damenproblem und Sudoku."},
        {"name": "StackOverflowError", "desc": "Jeder Aufruf belegt Platz auf dem Aufrufstapel. Fehlt der Basisfall oder wird das Problem nicht kleiner, läuft der Stapel über."},
    ]},
    {"title": "Datenstrukturen", "items": [
        {"name": "Verkettete Liste", "desc": "Knoten mit Wert und Referenz `next`. Einfügen und Löschen hängen nur Referenzen um (O(1), wenn man die Stelle hat), Suchen und Zugriff auf das i-te Element kosten O(n).",
         "code": "class Knoten {\n    int wert;\n    Knoten next;\n\n    Knoten(int wert) {\n        this.wert = wert;\n    }\n}\nKnoten kopf = new Knoten(5);\nkopf.next = new Knoten(9);\nfor (Knoten k = kopf; k != null; k = k.next) {\n    System.out.println(k.wert);\n}", "out": "5\n9\n"},
        {"name": "Stapel und Schlange", "desc": "Stapel (Stack): push und pop am selben Ende, LIFO. Schlange (Queue): hinten anstellen, vorne entnehmen, FIFO. Beide gehen mit Array oder verketteter Liste in O(1)."},
        {"name": "Binärer Suchbaum", "desc": "Jeder Knoten hat bis zu zwei Kinder: links alles Kleinere, rechts alles Größere. Suchen, Einfügen und Löschen kosten O(Höhe): ausgeglichen O(log n), entartet O(n)."},
        {"name": "Traversierungen", "desc": "Preorder: Knoten, links, rechts. Inorder: links, Knoten, rechts (beim Suchbaum sortiert). Postorder: links, rechts, Knoten.",
         "code": "class Knoten {\n    int wert;\n    Knoten kleiner, groesser;\n\n    Knoten(int wert) {\n        this.wert = wert;\n    }\n}\nstatic void inorder(Knoten k) {\n    if (k == null) {\n        return;\n    }\n    inorder(k.kleiner);\n    System.out.println(k.wert);\n    inorder(k.groesser);\n}\nKnoten wurzel = new Knoten(5);\nwurzel.kleiner = new Knoten(2);\nwurzel.groesser = new Knoten(8);\ninorder(wurzel);", "out": "2\n5\n8\n"},
        {"name": "Hashtabelle", "desc": "Die Hashfunktion berechnet aus dem Schlüssel den Index, z.B. `schluessel % groesse`. Suchen und Einfügen im Schnitt O(1). Eine Primzahl als Tabellengröße verteilt die Schlüssel gleichmäßiger.",
         "code": "int groesse = 7;\nSystem.out.println(15 % groesse);\nSystem.out.println(22 % groesse);", "out": "1\n1\n"},
        {"name": "Kollisionen", "desc": "Zwei Schlüssel mit demselben Index. Lösungen: Verkettung (jedes Fach ist eine Liste) oder offene Adressierung, z.B. lineares Sondieren: das nächste freie Fach nehmen, `(index + 1) % groesse`."},
    ]},
    {"title": "Suchen und Sortieren", "items": [
        {"name": "Lineare Suche", "desc": "Element für Element vergleichen. Funktioniert immer, kostet O(n).",
         "code": "int[] a = { 7, 3, 9 };\nint stelle = -1;\nfor (int i = 0; i < a.length; i++) {\n    if (a[i] == 9) {\n        stelle = i;\n    }\n}\nSystem.out.println(stelle);", "out": "2\n"},
        {"name": "Binäre Suche", "desc": "Nur in sortierten Daten: die Mitte ansehen und die Hälfte wegwerfen, in der das Ziel nicht liegen kann. O(log n).",
         "code": "int[] a = { 2, 5, 8, 12, 20 };\nint von = 0, bis = a.length - 1, ziel = 12, stelle = -1;\nwhile (von <= bis) {\n    int mitte = (von + bis) / 2;\n    if (a[mitte] == ziel) {\n        stelle = mitte;\n        break;\n    }\n    if (a[mitte] < ziel) {\n        von = mitte + 1;\n    } else {\n        bis = mitte - 1;\n    }\n}\nSystem.out.println(stelle);", "out": "3\n"},
        {"name": "Bubblesort", "desc": "Nachbarn vergleichen und tauschen, bis nichts mehr falsch steht. O(n²).",
         "code": "int[] a = { 5, 2, 9, 1 };\nfor (int i = 0; i < a.length - 1; i++) {\n    for (int j = 0; j < a.length - 1 - i; j++) {\n        if (a[j] > a[j + 1]) {\n            int merke = a[j];\n            a[j] = a[j + 1];\n            a[j + 1] = merke;\n        }\n    }\n}\nSystem.out.println(Arrays.toString(a));", "out": "[1, 2, 5, 9]\n"},
        {"name": "Selectionsort", "desc": "Das kleinste Element des Rests suchen und nach vorne tauschen. O(n²), aber nur n - 1 Tauschvorgänge.",
         "code": "int[] a = { 5, 2, 9, 1 };\nfor (int i = 0; i < a.length - 1; i++) {\n    int min = i;\n    for (int j = i + 1; j < a.length; j++) {\n        if (a[j] < a[min]) {\n            min = j;\n        }\n    }\n    int merke = a[i];\n    a[i] = a[min];\n    a[min] = merke;\n}\nSystem.out.println(Arrays.toString(a));", "out": "[1, 2, 5, 9]\n"},
        {"name": "Insertionsort", "desc": "Jedes Element in den schon sortierten vorderen Teil einschieben. O(n²), bei fast sortierten Daten aber fast O(n).",
         "code": "int[] a = { 5, 2, 9, 1 };\nfor (int i = 1; i < a.length; i++) {\n    int wert = a[i];\n    int j = i - 1;\n    while (j >= 0 && a[j] > wert) {\n        a[j + 1] = a[j];\n        j--;\n    }\n    a[j + 1] = wert;\n}\nSystem.out.println(Arrays.toString(a));", "out": "[1, 2, 5, 9]\n"},
        {"name": "Quicksort", "desc": "Teile und herrsche: um ein Pivot aufteilen (kleinere links, größere rechts), beide Teile rekursiv sortieren. Im Schnitt O(n log n), im schlechtesten Fall O(n²)."},
        {"name": "Mergesort", "desc": "Teile und herrsche: halbieren, beide Hälften rekursiv sortieren, dann zusammenmischen. Immer O(n log n), braucht aber zusätzlichen Speicher."},
        {"name": "Stabil und in-place", "desc": "Stabil: Gleiche Elemente behalten ihre Reihenfolge (Mergesort, Insertionsort, Bubblesort). In-place: braucht keinen zweiten Speicherbereich (Quicksort, Bubblesort, Selectionsort)."},
    ]},
]
